import { Group, Euler } from 'three/webgpu';
import gsap from 'gsap';

/**
 * @param {Object} config - Node configuration
 * @param {Object} ctx - Context with loaders and utilities
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Create the root group
  const root = new Group();
  root.name = config.id || 'ornamental-divider';

  // Load the GLB mesh (synchronous from cache)
  const loadedGroup = ctx.glbLoader(config.meshUrl).clone(true);
  const mesh = loadedGroup.children[0]; // Assume single mesh child

  // Apply scene placement transforms
  const { position, rotation, scale } = config.scenePlacement || {};
  if (position) {
    root.position.set(position.x || 0, position.y || 0, position.z || 0);
  }
  if (rotation) {
    const euler = new Euler(rotation.x || 0, rotation.y || 0, rotation.z || 0);
    root.quaternion.setFromEuler(euler);
  }
  if (scale) {
    root.scale.set(scale.x || 1, scale.y || 1, scale.z || 1);
  }

  // Add the mesh as child (so transforms on root apply)
  root.add(loadedGroup);

  // Store original Y position for hover animation
  const baseY = root.position.y;

  // --- Interaction handlers ---
  root.userData.handlers = {
    hoverEnter: () => {
      gsap.killTweensOf(root.position);
      gsap.to(root.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: true,
      });
    },
    hoverLeave: () => {
      gsap.killTweensOf(root.position);
      gsap.to(root.position, {
        y: baseY,
        duration: 0.5,
        ease: 'power2.out',
        overwrite: true,
      });
    },
    click: () => {
      // Emit event for hub-home.select (handled by parent scene manager)
      // The scene manager is expected to check userData.handlers.click
      // and dispatch the appropriate event.
      // For now we just trigger the event via a hypothetical global emitter.
      if (typeof ctx.emit === 'function') {
        ctx.emit('hub-home.select', { source: config.id });
      } else {
        // Fallback: set a custom data property for external reading
        root.userData.lastEvent = 'hub-home.select';
      }
    },
  };

  // --- Data binding placeholder (trpc.visits.book.slot -> confirmPanel) ---
  // This would typically be wired in the parent scene; we leave it empty.
  // root.userData.dataBindings = config.dataBindings || [];

  // --- Cleanup ---
  root.userData.cleanup = () => {
    // Kill all GSAP tweens targeting this object
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root);

    // Dispose mesh and its materials/geometries
    if (loadedGroup && loadedGroup.children) {
      loadedGroup.traverse((child) => {
        if (child.isMesh) {
          child.geometry?.dispose();
          if (Array.isArray(child.material)) {
            child.material.forEach((mat) => mat.dispose());
          } else if (child.material) {
            child.material.dispose();
          }
        }
      });
    }

    // Remove from parent (optional, but good practice)
    if (root.parent) {
      root.parent.remove(root);
    }
  };

  return root;
}
